# ---------------------------------------------------------------------------
# 1. Load metadata and saved models (no training occurs in this application)
# ---------------------------------------------------------------------------

@st.cache_data
def load_metadata() -> dict:
    """Read feature names and training metadata saved by training.py."""
    if not METADATA_PATH.exists():
        raise FileNotFoundError(
            "model/metadata.json is missing. Check that the model folder is in the repository."
        )
    with METADATA_PATH.open("r", encoding="utf-8") as metadata_file:
        return json.load(metadata_file)


@st.cache_resource
def load_saved_models() -> Dict[str, object]:
    """Load the five existing model pipelines once and reuse them on reruns."""
    loaded_models = {}
    for model_name, file_name in MODEL_FILE_NAMES.items():
        model_path = MODEL_DIR / file_name
        if not model_path.exists():
            raise FileNotFoundError(
                f"Saved model not found: {model_path.relative_to(PROJECT_DIR)}. "
                "Check that all five model files are present in the model folder."
            )
        loaded_models[model_name] = joblib.load(model_path)
    return loaded_models


# ---------------------------------------------------------------------------
# 2. Validate the uploaded CSV before making predictions
# ---------------------------------------------------------------------------

def convert_target_labels(target_values: pd.Series) -> pd.Series:
    """Accept readable class names or the original -1/+1 target values."""
    mapping = {
        "-1": PHISHING_LABEL,
        "-1.0": PHISHING_LABEL,
        "phishing": PHISHING_LABEL,
        "+1": LEGITIMATE_LABEL,
        "1": LEGITIMATE_LABEL,
        "1.0": LEGITIMATE_LABEL,
        "legitimate": LEGITIMATE_LABEL,
    }
    converted = target_values.astype(str).str.strip().str.lower().map(mapping)
    if converted.isna().any():
        unknown_values = target_values[converted.isna()].astype(str).unique().tolist()
        raise ValueError(
            "The Result column contains unrecognised labels: "
            f"{unknown_values}. Use -1/+1 or Phishing/Legitimate."
        )
    return converted


def validate_uploaded_data(
    uploaded_df: pd.DataFrame,
    feature_names: list[str],
) -> Tuple[pd.DataFrame, pd.Series]:
    """Validate columns and values, preserving the exact training feature order."""
    required_columns = feature_names + [TARGET_COLUMN]
    missing_columns = [name for name in required_columns if name not in uploaded_df.columns]
    if missing_columns:
        raise ValueError(
            "The uploaded CSV is missing these required columns: "
            + ", ".join(missing_columns)
        )
    if uploaded_df.empty:
        raise ValueError("The uploaded CSV contains no data rows.")

    # Select columns using metadata order, not the order in the uploaded file.
    X_uploaded = uploaded_df[feature_names].copy()
    for column in feature_names:
        X_uploaded[column] = pd.to_numeric(X_uploaded[column], errors="coerce")

    if X_uploaded.isna().any().any():
        bad_columns = X_uploaded.columns[X_uploaded.isna().any()].tolist()
        raise ValueError(
            "Some feature values are missing or non-numeric in these columns: "
            + ", ".join(bad_columns)
        )

    y_actual = convert_target_labels(uploaded_df[TARGET_COLUMN])
    return X_uploaded, y_actual


# ---------------------------------------------------------------------------
# 3. Evaluate saved models and format the results
# ---------------------------------------------------------------------------

def evaluate_one_model(
    model: object,
    X_uploaded: pd.DataFrame,
    y_actual: pd.Series,
) -> Tuple[dict, pd.Series, dict, object]:
    """Predict with a fitted model and calculate the six required metrics."""
    # Deliberately no model.fit() call: the saved pipeline is used as-is.
    y_predicted = pd.Series(model.predict(X_uploaded), index=y_actual.index)

    class_names = list(model.classes_)
    phishing_column = class_names.index(PHISHING_LABEL)
    phishing_probabilities = model.predict_proba(X_uploaded)[:, phishing_column]
    actual_phishing = (y_actual == PHISHING_LABEL).astype(int)

    metrics = {
        "Accuracy": float(accuracy_score(y_actual, y_predicted)),
        "AUC": float(roc_auc_score(actual_phishing, phishing_probabilities)),
        "Precision": float(
            precision_score(
                y_actual,
                y_predicted,
                pos_label=PHISHING_LABEL,
                zero_division=0,
            )
        ),
        "Recall": float(
            recall_score(
                y_actual,
                y_predicted,
                pos_label=PHISHING_LABEL,
                zero_division=0,
            )
        ),
        "F1": float(
            f1_score(
                y_actual,
                y_predicted,
                pos_label=PHISHING_LABEL,
                zero_division=0,
            )
        ),
        "MCC": float(matthews_corrcoef(y_actual, y_predicted)),
    }

    report = classification_report(
        y_actual,
        y_predicted,
        labels=LABEL_ORDER,
        target_names=LABEL_ORDER,
        output_dict=True,
        zero_division=0,
    )
    matrix = confusion_matrix(y_actual, y_predicted, labels=LABEL_ORDER)
    return metrics, y_predicted, report, matrix


def format_metric(metric_name: str, metric_value: float) -> str:
    """Format rate metrics as percentages and the remaining scores as decimals."""
    if metric_name in {"Accuracy", "Precision", "Recall"}:
        return f"{metric_value:.2%}"
    return f"{metric_value:.4f}"


def build_metric_cards(metrics: dict) -> str:
    """Return accessible, restrained HTML cards for the six evaluation metrics."""
    metric_specs = [
        ("Accuracy", "Accuracy", "Overall correct classifications", "teal"),
        ("AUC", "AUC", "Ability to separate the two classes", "blue"),
        ("Precision", "Precision", "Phishing alerts that are correct", "amber"),
        ("Recall", "Recall", "Phishing cases successfully detected", "teal"),
        ("F1", "F1 score", "Balance between precision and recall", "blue"),
        ("MCC", "MCC", "Balanced measure of prediction quality", "slate"),
    ]
    cards = []
    for key, label, helper, accent in metric_specs:
        value = html.escape(format_metric(key, metrics[key]))
        safe_label = html.escape(label)
        safe_helper = html.escape(helper)
        cards.append(
            f'<article class="metric-card accent-{accent}">'
            f'<div class="metric-card-label">{safe_label}</div>'
            f'<div class="metric-card-value">{value}</div>'
            f'<div class="metric-card-helper">{safe_helper}</div>'
            "</article>"
        )
    return '<div class="metric-grid">' + "".join(cards) + "</div>"


def create_confusion_figure(matrix, model_name: str):
    """Create a compact two-class confusion matrix with a meaningful legend.

    Teal cells on the diagonal represent correct predictions. Amber cells
    away from the diagonal represent misclassifications.
    """
    figure, axis = plt.subplots(figsize=(5.6, 4.05), dpi=125)
    figure.patch.set_facecolor("#ffffff")
    axis.set_facecolor("#ffffff")

    descriptions = {
        (0, 0): "TP · detected",
        (0, 1): "FN · missed",
        (1, 0): "FP · false alarm",
        (1, 1): "TN · legitimate",
    }
    correct_fill = "#DDF4EF"
    error_fill = "#FFF0D9"
    correct_edge = "#79C8B7"
    error_edge = "#E6BD78"

    for row in range(2):
        for column in range(2):
            is_correct = row == column
            fill = correct_fill if is_correct else error_fill
            edge = correct_edge if is_correct else error_edge
            axis.add_patch(
                Rectangle(
                    (column, row),
                    1,
                    1,
                    facecolor=fill,
                    edgecolor=edge,
                    linewidth=1.8,
                )
            )
            count = int(matrix[row][column])
            count_color = "#12675D" if is_correct else "#966018"
            axis.text(
                column + 0.5,
                row + 0.43,
                f"{count:,}",
                ha="center",
                va="center",
                fontsize=18,
                fontweight="bold",
                color=count_color,
            )
            axis.text(
                column + 0.5,
                row + 0.69,
                descriptions[(row, column)],
                ha="center",
                va="center",
                fontsize=7.1,
                color="#52647A",
            )

    axis.set_xlim(0, 2)
    axis.set_ylim(2, 0)
    axis.set_aspect("equal")
    axis.set_xticks([0.5, 1.5])
    axis.set_xticklabels(LABEL_ORDER, fontsize=9, color="#27384B")
    axis.set_yticks([0.5, 1.5])
    axis.set_yticklabels(LABEL_ORDER, fontsize=9, color="#27384B")
    axis.set_xlabel("Predicted class", fontsize=9, labelpad=9, color="#27384B")
    axis.set_ylabel("Actual class", fontsize=9, labelpad=9, color="#27384B")
    axis.set_title(
        f"{model_name} · Confusion matrix",
        fontsize=11,
        fontweight="bold",
        color="#17283D",
        pad=13,
    )
    for spine in axis.spines.values():
        spine.set_visible(False)
    axis.tick_params(length=0, pad=8)

    legend_items = [
        Patch(facecolor=correct_fill, edgecolor=correct_edge, label="Correct predictions"),
        Patch(facecolor=error_fill, edgecolor=error_edge, label="Misclassifications"),
    ]
    figure.legend(
        handles=legend_items,
        loc="lower center",
        bbox_to_anchor=(0.5, 0.025),
        ncol=2,
        frameon=False,
        fontsize=8,
        labelcolor="#52647A",
        handlelength=1.3,
        columnspacing=1.7,
    )
    figure.subplots_adjust(left=0.20, right=0.98, top=0.84, bottom=0.24)
    return figure


